<?php
namespace Tests\Feature\Customer;

use App\Models\Category;use App\Models\Color;use App\Models\Coupon;use App\Models\Order;use App\Models\Product;use App\Models\ProductVariant;use App\Models\ShippingZone;use App\Models\Size;use App\Models\User;
use App\Services\CartService;use App\Services\OrderService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Tests\TestCase;

class Phase5OrderTest extends TestCase
{
    use RefreshDatabase; private int $n=0;
    private function user(string $role='customer'):User{return User::factory()->create(['role'=>$role,'status'=>'active']);}
    private function variant(int $stock=5,float $price=500000):ProductVariant{$this->n++;$c=Category::create(['name'=>'C'.$this->n,'slug'=>'c-'.$this->n,'status'=>'active']);$p=Product::create(['category_id'=>$c->id,'name'=>'Shirt '.$this->n,'slug'=>'shirt-'.$this->n,'sku'=>'P-'.$this->n,'price'=>$price,'status'=>'active']);$color=Color::create(['name'=>'Navy '.$this->n,'hex_code'=>'#112233','status'=>'active']);$size=Size::create(['name'=>'M'.$this->n,'status'=>'active']);return $p->variants()->create(['color_id'=>$color->id,'size_id'=>$size->id,'sku'=>'V-'.$this->n,'stock'=>$stock]);}
    private function zone(float $fee=30000):ShippingZone{$this->n++;$z=ShippingZone::create(['name'=>'Zone '.$this->n,'code'=>'Z'.$this->n,'status'=>'active']);$z->rates()->create(['name'=>'Standard','fee'=>$fee,'free_shipping_threshold'=>1000000,'status'=>'active']);return $z;}
    private function address():array{return ['recipient_name'=>'Nguyen Van A','email'=>'a@example.com','phone'=>'0900000000','province'=>'HCM','district'=>'1','ward'=>'Ben Nghe','address'=>'1 Nguyen Hue','note'=>null];}
    private function coupon(array $a=[]):Coupon{$this->n++;return Coupon::create(array_merge(['code'=>'CP'.$this->n,'type'=>'percent','value'=>10,'minimum_order'=>0,'status'=>'active'],$a));}
    private function place(User $u,ProductVariant $v,int $qty=1,?Coupon $coupon=null,?ShippingZone $zone=null,?string $token=null):Order{app(CartService::class)->add($u,$v,$qty);return app(OrderService::class)->placeOrder($u,$this->address(),$token??fake()->uuid(),$coupon?->code,($zone??$this->zone())->id);}
    private function payload(string $token,int $zone):array{return $this->address()+['checkout_token'=>$token,'shipping_zone_id'=>$zone];}

    public function test_customer_checkout_page_200():void{$u=$this->user();app(CartService::class)->add($u,$this->variant(),1);$this->withSession(['shipping_zone_id'=>$this->zone()->id])->actingAs($u)->get('/checkout')->assertOk()->assertSee('Thanh toán');}
    public function test_admin_blocked_checkout():void{$this->actingAs($this->user('admin'))->get('/checkout')->assertRedirect(route('admin.dashboard'));}
    public function test_empty_cart_cannot_checkout():void{$this->actingAs($this->user())->get('/checkout')->assertRedirect(route('cart.index'));}
    public function test_place_order_success():void{$o=$this->place($this->user(),$this->variant());$this->assertDatabaseHas('orders',['id'=>$o->id]);}
    public function test_order_status_starts_pending():void{$this->assertSame('pending',$this->place($this->user(),$this->variant())->status);}
    public function test_order_item_snapshot_correctly():void{$v=$this->variant();$o=$this->place($this->user(),$v,2);$i=$o->items->first();$this->assertSame($v->product->name,$i->product_name);$this->assertSame($v->color->name,$i->color_name);$this->assertEquals(1000000,$i->subtotal);}
    public function test_order_code_unique_and_correct_format():void{$a=$this->place($this->user(),$this->variant());$b=$this->place($this->user(),$this->variant());$this->assertMatchesRegularExpression('/^ORD\d{8}\d{8}$/',$a->order_code);$this->assertNotSame($a->order_code,$b->order_code);}
    public function test_stock_decreases_only_after_successful_order():void{$u=$this->user();$v=$this->variant(5);app(CartService::class)->add($u,$v,2);$this->assertEquals(5,$v->fresh()->stock);app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),null,$this->zone()->id);$this->assertEquals(3,$v->fresh()->stock);}
    public function test_stock_cannot_become_negative_under_sequential_contention():void{$v=$this->variant(1);$a=$this->user();$b=$this->user();app(CartService::class)->add($a,$v,1);app(CartService::class)->add($b,$v,1);app(OrderService::class)->placeOrder($a,$this->address(),fake()->uuid(),null,$this->zone()->id);try{app(OrderService::class)->placeOrder($b,$this->address(),fake()->uuid(),null,$this->zone()->id);}catch(ValidationException){}$this->assertEquals(0,$v->fresh()->stock);$this->assertEquals(1,Order::count());}
    public function test_insufficient_stock_rejected():void{$u=$this->user();$v=$this->variant(2);app(CartService::class)->add($u,$v,2);$v->update(['stock'=>1]);$this->expectException(ValidationException::class);app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),null,$this->zone()->id);}
    public function test_coupon_usage_recorded_only_after_success():void{$u=$this->user();$v=$this->variant();$c=$this->coupon();app(CartService::class)->add($u,$v,1);$this->assertDatabaseCount('coupon_usages',0);$o=app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),$c->code,$this->zone()->id);$this->assertDatabaseHas('coupon_usages',['order_id'=>$o->id]);}
    public function test_coupon_usage_limit_enforced():void{$c=$this->coupon(['usage_limit'=>1,'used_count'=>1]);$u=$this->user();app(CartService::class)->add($u,$this->variant(),1);$this->expectException(ValidationException::class);app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),$c->code,$this->zone()->id);}
    public function test_shipping_recalculated_server_side():void{$o=$this->place($this->user(),$this->variant(),1,null,$this->zone(47000));$this->assertEquals(47000,$o->shipping_fee);}
    public function test_price_recalculated_server_side():void{$u=$this->user();$v=$this->variant(5,500000);app(CartService::class)->add($u,$v,1);$v->product->update(['sale_price'=>350000,'sale_start'=>now()->subMinute(),'sale_end'=>now()->addHour()]);$o=app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),null,$this->zone()->id);$this->assertEquals(350000,$o->subtotal);}
    public function test_cart_cleared_after_success():void{$u=$this->user();$this->place($u,$this->variant());$this->assertEquals(0,$u->cart->items()->count());}
    public function test_cart_preserved_if_transaction_fails():void{$u=$this->user();$v=$this->variant(2);app(CartService::class)->add($u,$v,2);$v->update(['stock'=>1]);try{app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),null,$this->zone()->id);}catch(ValidationException){}$this->assertEquals(1,$u->cart->items()->count());}
    public function test_duplicate_submit_does_not_create_two_orders():void{$u=$this->user();$v=$this->variant();$z=$this->zone();app(CartService::class)->add($u,$v,1);$t=fake()->uuid();$s=app(OrderService::class);$a=$s->placeOrder($u,$this->address(),$t,null,$z->id);$b=$s->placeOrder($u,$this->address(),$t,null,$z->id);$this->assertSame($a->id,$b->id);$this->assertEquals(1,Order::count());}
    public function test_customer_sees_own_order_history():void{$u=$this->user();$o=$this->place($u,$this->variant());$this->actingAs($u)->get('/account/orders')->assertOk()->assertSee($o->order_code);}
    public function test_customer_cannot_see_another_order():void{$o=$this->place($this->user(),$this->variant());$this->actingAs($this->user())->get('/account/orders/'.$o->id)->assertNotFound();}
    public function test_customer_can_cancel_pending_order():void{$u=$this->user();$o=$this->place($u,$this->variant());app(OrderService::class)->cancelOrder($u,$o,'Đổi ý');$this->assertSame('cancelled',$o->fresh()->status);}
    public function test_customer_cannot_cancel_non_pending_order():void{$u=$this->user();$o=$this->place($u,$this->variant());$o->update(['status'=>'confirmed']);$this->expectException(ValidationException::class);app(OrderService::class)->cancelOrder($u,$o,'Đổi ý');}
    public function test_cancel_restores_stock_exactly_once():void{$u=$this->user();$v=$this->variant(5);$o=$this->place($u,$v,2);app(OrderService::class)->cancelOrder($u,$o,'Đổi ý');$this->assertEquals(5,$v->fresh()->stock);}
    public function test_double_cancel_does_not_restore_stock_twice():void{$u=$this->user();$v=$this->variant(5);$o=$this->place($u,$v,2);$s=app(OrderService::class);$s->cancelOrder($u,$o,'Đổi ý');try{$s->cancelOrder($u,$o,'Lần hai');}catch(ValidationException){}$this->assertEquals(5,$v->fresh()->stock);}
    public function test_cancel_restores_coupon_usage():void{$u=$this->user();$c=$this->coupon();$o=$this->place($u,$this->variant(),1,$c);app(OrderService::class)->cancelOrder($u,$o,'Đổi ý');$this->assertDatabaseMissing('coupon_usages',['order_id'=>$o->id]);$this->assertEquals(0,$c->fresh()->used_count);}
    public function test_transaction_rollback_keeps_stock_order_coupon_consistent():void{$u=$this->user();$a=$this->variant(3);$b=$this->variant(2);$c=$this->coupon();app(CartService::class)->add($u,$a,2);app(CartService::class)->add($u,$b,2);$b->update(['stock'=>1]);try{app(OrderService::class)->placeOrder($u,$this->address(),fake()->uuid(),$c->code,$this->zone()->id);}catch(ValidationException){}$this->assertEquals(3,$a->fresh()->stock);$this->assertEquals(0,Order::count());$this->assertEquals(0,$c->fresh()->used_count);$this->assertDatabaseCount('coupon_usages',0);}
}
